-- NEW_FILE: 8f9a8a82_retry1_aristotle/Catalog/Geometry/EulerCharInclusionExclusion.lean
/-
# Inclusion–Exclusion for the Euler Characteristic of Finite Simplicial Complexes

This module formalizes the inclusion–exclusion formula for the (combinatorial) Euler
characteristic of a finite "face set" — an arbitrary `Finset (Finset V)`, thought of as a
collection of faces (simplices) of a finite simplicial complex.

All proofs are purely combinatorial / finite-set arguments: no homology, homotopy, or
nerve-theorem results are used. The dependency structure is acyclic:

* `eulerChar_union_eq_add_sub_inter` (two–set inclusion–exclusion) is proved directly from
  `Finset.sum_union_inter`.
* `eulerChar_inclusion_exclusion` (general inclusion–exclusion over a finite index set) is
  proved by induction on the index set, using only the two–set result above.
* `eulerChar_eq_sum_card_filter` (grouping by cardinality / dimension) is independent of the
  other two and follows from `Finset.sum_fiberwise_of_maps_to`.
-/
import Mathlib

open Finset

namespace EulerCharIE

variable {V : Type*} [Fintype V] [DecidableEq V]

/-- The combinatorial Euler characteristic of a finite face set `X : Finset (Finset V)`:
the alternating sum `∑_{σ ∈ X} (-1)^{|σ|}` over faces, weighted by the parity of their
cardinality. -/
def eulerChar (X : Finset (Finset V)) : ℤ :=
  X.sum fun σ => (-1 : ℤ) ^ σ.card

omit [Fintype V] [DecidableEq V] in
@[simp] theorem eulerChar_empty : eulerChar (∅ : Finset (Finset V)) = 0 := by
  simp [eulerChar]

/-
**Theorem 1 (two–set inclusion–exclusion).** For any two face sets `A` and `B`,
`χ(A ∪ B) = χ(A) + χ(B) - χ(A ∩ B)`. This is a pure finite-set counting fact: it holds for
the sum of any function over finsets, here applied to `σ ↦ (-1)^{|σ|}`.
-/
omit [Fintype V] in
theorem eulerChar_union_eq_add_sub_inter (A B : Finset (Finset V)) :
    eulerChar (A ∪ B) = eulerChar A + eulerChar B - eulerChar (A ∩ B) := by
  unfold eulerChar; rw [ ← Finset.sum_union_inter ] ; ring;

/-
**Theorem 2 (general inclusion–exclusion).** For a finite index set `s` and a family of
face sets `A i`, the Euler characteristic of the union `⨆_{i ∈ s} A i` equals the alternating
sum over the nonempty subsets `T ⊆ s` of the Euler characteristic of the intersection
`⋂_{i ∈ T} A i` (written `T.inf A`), with sign `(-1)^{|T|+1}`.

Proved by induction on `s` using only `eulerChar_union_eq_add_sub_inter`.
-/
set_option maxHeartbeats 1000000 in
theorem eulerChar_inclusion_exclusion {ι : Type*} [DecidableEq ι]
    (s : Finset ι) (A : ι → Finset (Finset V)) :
    eulerChar (s.sup A) =
      ∑ T ∈ s.powerset.filter (·.Nonempty),
        (-1 : ℤ) ^ (T.card + 1) * eulerChar (T.inf A) := by
  induction' s using Finset.induction with a s ha ih generalizing A;
  · aesop;
  · have h_split : ∑ T ∈ (insert a s).powerset.filter (·.Nonempty), (-1 : ℤ) ^ (T.card + 1) * eulerChar (T.inf A) = (∑ T ∈ s.powerset.filter (·.Nonempty), (-1 : ℤ) ^ (T.card + 1) * eulerChar (T.inf A)) + eulerChar (A a) + ∑ T ∈ s.powerset.filter (·.Nonempty), (-1 : ℤ) ^ (T.card + 2) * eulerChar ((insert a T).inf A) := by
      have h_split : (insert a s).powerset.filter (·.Nonempty) = (s.powerset.filter (·.Nonempty)) ∪ { {a} } ∪ (s.powerset.filter (·.Nonempty)).image (fun T => insert a T) := by
        ext T; simp [Finset.mem_union, Finset.mem_image];
        constructor;
        · intro hT
          by_cases haT : a ∈ T;
          · by_cases hT' : T = {a};
            · exact Or.inl hT';
            · refine' Or.inr ( Or.inr ⟨ T.erase a, _, _ ⟩ );
              · grind;
              · rw [ Finset.insert_erase haT ];
          · exact Or.inr <| Or.inl ⟨ fun x hx => by have := hT.1 hx; aesop, hT.2 ⟩;
        · rintro ( rfl | ⟨ hT₁, hT₂ ⟩ | ⟨ T, ⟨ hT₁, hT₂ ⟩, rfl ⟩ ) <;> simp_all +decide [ Finset.subset_iff ];
      rw [ h_split, Finset.sum_union, Finset.sum_union ] <;> norm_num;
      · rw [ Finset.sum_image ] <;> simp +decide;
        · refine' Finset.sum_congr rfl fun x hx => _;
          grind;
        · intro x hx y hy; simp_all +decide [ Finset.ext_iff ] ;
          grind;
      · exact ha;
      · simp +decide [ Finset.disjoint_right, Finset.mem_image ];
        grind +suggestions;
    have h_split : eulerChar (A a ⊓ s.sup A) = ∑ T ∈ s.powerset.filter (·.Nonempty), (-1 : ℤ) ^ (T.card + 1) * eulerChar ((insert a T).inf A) := by
      convert ih ( fun i => A a ⊓ A i ) using 1;
      · congr! 1;
        ext; simp +decide [ Finset.mem_sup ] ;
        exact ⟨ fun ⟨ h₁, i, hi, h₂ ⟩ => ⟨ i, hi, h₁, h₂ ⟩, fun ⟨ i, hi, h₁, h₂ ⟩ => ⟨ h₁, i, hi, h₂ ⟩ ⟩;
      · congr! 3;
        ext; simp +decide [ Finset.mem_inf ] ;
        exact ⟨ fun h i hi => ⟨ h.1, h.2 i hi ⟩, fun h => ⟨ h _ ( Classical.choose_spec ( Finset.nonempty_of_ne_empty ( by aesop ) ) ) |>.1, fun i hi => h i hi |>.2 ⟩ ⟩;
    have := eulerChar_union_eq_add_sub_inter ( A a ) ( s.sup A ) ; simp_all +decide [ pow_succ' ] ;
    ring

/-
**Theorem 3 (grouping by cardinality / dimension).** The Euler characteristic can be
computed by grouping faces according to their cardinality `c = |σ|`:
`χ(X) = ∑_{c} (-1)^c · #{σ ∈ X : |σ| = c}`.

Remark on indexing: a face `σ` of "dimension" `d` has `|σ| = d + 1` vertices, so its
contribution to `χ` is `(-1)^{|σ|} = (-1)^{d+1}`. (PROMPT.md wrote the sign of the dimension-`d`
term as `(-1)^d`; the mathematically correct sign is `(-1)^{d+1}`, equivalently `(-1)^c` when
grouping by cardinality `c = d + 1` as done here.) Note also that the empty face `σ = ∅`, when
present, contributes the `c = 0` term and is not a positive-dimensional simplex.
-/
omit [DecidableEq V] in
theorem eulerChar_eq_sum_card_filter (X : Finset (Finset V)) :
    eulerChar X =
      ∑ c ∈ Finset.range (Fintype.card V + 1),
        (-1 : ℤ) ^ c * ((X.filter (fun σ => σ.card = c)).card : ℤ) := by
  have := Finset.sum_fiberwise_of_maps_to ( show ∀ σ ∈ X, σ.card ∈ Finset.range ( Fintype.card V + 1 ) from fun σ hσ => Finset.mem_range_succ_iff.mpr ( le_trans ( Finset.card_le_univ _ ) <| by simp +decide ) ) ( fun σ ↦ ( -1 : ℤ ) ^ σ.card ) ; simp_all +decide [ eulerChar ];
  rw [ ← this, Finset.sum_congr rfl ] ; intros ; rw [ Finset.sum_congr rfl fun x hx => by rw [ Finset.mem_filter.mp hx |>.2 ] ] ; simp +decide [ mul_comm ]

end EulerCharIE
